55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE = 0.1;
57	
58	const basePremiumOf = (item: Item): number => 100;
59	
60	const quote = (step: QuoteStep): QuoteResult => {
61	  const base = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
62	  const total = base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
63	  return { premium: Math.ceil(total) };
64	};
65	
66	export const runScenario = (scenario: Scenario): ScenarioOutput => {
67	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
68	};
